select jsonb_build_object('rpc',(select jsonb_build_object('md5',md5(prosrc),'owner',pg_get_userbyid(proowner),'security_definer',prosecdef,'settings',proconfig,'anon',has_function_privilege('anon',oid,'execute'),'authenticated',has_function_privilege('authenticated',oid,'execute'),'service_role',has_function_privilege('service_role',oid,'execute')) from pg_proc where oid='public.iap_post_verified_purchase(uuid,text,text,text,timestamptz)'::regprocedure),'migration',(select name from supabase_migrations.schema_migrations where version='20261009000200'),'iap_grants',(select count(*) from public.credit_grants where external_reference like 'iap/%')) as iap_postflight;
